\coordinate (A) at (0,0);
\coordinate (D) at (2,0);
\coordinate (C) at (4,0);
\coordinate (B) at (1,1.73205);
\draw (A)--(B)--(C)--cycle;
\draw (B)--(D);
\path (A) node[below left] {$A$} (D) node[below] {$D$} (C) node[below right] {$C$} (B) node[above] {$B$};
\end{tikzpicture}
[/tikz]

