mastery.question_text:
[tikz]
\begin{tikzpicture}[scale=1]
\coordinate (A) at (-1.8,0);
\coordinate (M) at (0,0);
\coordinate (C) at (1.8,0);
\coordinate (B) at (-0.9,1.559);
\tikzset{tk/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}},tkk/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (-2.5pt,-4pt)--(-2.5pt,4pt);\draw (2.5pt,-4pt)--(2.5pt,4pt);}}}}}
\draw[tk] (A)--(M);
\draw[tk] (M)--(C);
\draw[tk] (B)--(A);
\draw[tk] (B)--(M);
\draw (B)--(C);
\fill (M) circle (1.6pt);
\node[below left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[below] at (M) {$M$};
\node[below right] at (C) {$C$};
\end{tikzpicture}
[/tikz]
$A$, $M$ and $C$ lie on a straight line.
$\triangle ABM$ is equilateral and $MB=MC$.
Prove that $\angle ABC=90^{\circ}$.

mastery.solution_text:
[tikz]
\begin{tikzpicture}[scale=1]
\coordinate (A) at (-1.8,0);
\coordinate (M) at (0,0);
\coordinate (C) at (1.8,0);
\coordinate (B) at (-0.9,1.559);
\tikzset{tk/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}},tkk/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (-2.5pt,-4pt)--(-2.5pt,4pt);\draw (2.5pt,-4pt)--(2.5pt,4pt);}}}}}
\draw[tk] (A)--(M);
\draw[tk] (M)--(C);
\draw[tk] (B)--(A);
\draw[tk] (B)--(M);
\draw (B)--(C);
\fill (M) circle (1.6pt);
\node[below left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[below] at (M) {$M$};
\node[below right] at (C) {$C$};
\pic[draw,"$60^{\circ}$",angle radius=0.55cm,angle eccentricity=1.9] {angle=B--M--A};
\pic[draw,"$120^{\circ}$",angle radius=0.75cm,angle eccentricity=1.55] {angle=C--M--B};
\pic[draw,"$30^{\circ}$",angle radius=0.6cm,angle eccentricity=1.9] {angle=M--B--C};
\end{tikzpicture}
[/tikz]
$\angle AMB=60^{\circ}$ (angle of the equilateral $\triangle ABM$)
$\angle BMC=180^{\circ}-60^{\circ}=120^{\circ}$ (angles on the straight line $AMC$)
$MB=MC$, so $\triangle BMC$ is isosceles, giving $\angle MBC=(180^{\circ}-120^{\circ})\div2=30^{\circ}$
$\angle ABC=\angle ABM+\angle MBC=60^{\circ}+30^{\circ}$
$=90^{\circ}$

